import React, { useState, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import io from 'socket.io-client';

const supabase = createClient(
    'https://ixikhufrylaugpdxokwu.supabase.co',
    'sb_publishable_7T38wLjTEs7UJKMMTxl9tQ_OLM6Wsf3'
);

const StaffDashboard = ({ clinicId, staffId, staffName }) => {
    const [queue, setQueue] = useState([]);
    const [summary, setSummary] = useState({
        total_waiting: 0,
        in_consultation_count: 0,
        completed_today: 0,
        average_wait_minutes: 0
    });
    const [socket, setSocket] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    
    useEffect(() => {
        const newSocket = io('http://localhost:3001', {
            auth: { userId: staffId, role: 'staff', clinicId }
        });
        setSocket(newSocket);
        
        newSocket.on('queue:updated', () => {
            console.log('Real-time update received - refreshing data...');
            fetchQueueFromDB();
            fetchSummary();
        });
        
        fetchQueueFromDB();
        fetchSummary();
        
        // Refresh every 30 seconds
        const interval = setInterval(() => {
            fetchQueueFromDB();
            fetchSummary();
        }, 30000);
        
        return () => {
            newSocket.close();
            clearInterval(interval);
        };
    }, [clinicId]);
    
    const fetchQueueFromDB = async () => {
        try {
            setLoading(true);
            
            // Get all waiting and in-consultation appointments
            const { data, error } = await supabase
                .from('Appointments')
                .select('*')
                .in('status', ['waiting', 'in_consultation'])
                .order('arrived_at', { ascending: true });
            
            if (error) {
                console.error('Supabase error:', error);
                setError(error.message);
                setLoading(false);
                return;
            }
            
            console.log('Fetched appointments:', data);
            
            if (!data || data.length === 0) {
                setQueue([]);
                setLoading(false);
                return;
            }
            
            const filteredData = clinicId 
                ? data.filter(item => item.ClinicID === clinicId)
                : data;
            
            const now = new Date();
            const formattedQueue = filteredData.map((item, idx) => {
                let waitMinutes = 0;
                let waitDisplay = '';
                let waitColor = '#6b7280';
                
                if (item.arrived_at) {
                    const arrived = new Date(item.arrived_at);
                    waitMinutes = Math.floor((now - arrived) / 60000);
                    
                    if (waitMinutes < 60) {
                        waitDisplay = `${waitMinutes} min`;
                    } else {
                        const hours = Math.floor(waitMinutes / 60);
                        const mins = waitMinutes % 60;
                        waitDisplay = `${hours}h ${mins}m`;
                    }
                    
                    if (waitMinutes > 60) {
                        waitColor = '#dc2626';
                    } else if (waitMinutes > 30) {
                        waitColor = '#f59e0b';
                    } else if (waitMinutes > 15) {
                        waitColor = '#eab308';
                    } else {
                        waitColor = '#10b981';
                    }
                }
                
                return {
                    appointment_id: item.id,
                    queue_position: idx + 1,
                    patient_name: item.patient_name,
                    waiting_minutes: waitMinutes,
                    wait_display: waitDisplay,
                    wait_color: waitColor,
                    patient_status: item.status,
                    is_walk_in: item.is_walk_in || false,
                    arrived_at: item.arrived_at,
                    arrived_time: item.arrived_at ? new Date(item.arrived_at).toLocaleTimeString() : 'Unknown',
                    clinic_id: item.ClinicID,
                    reason: item.reason || 'General checkup'
                };
            });
            
            setQueue(formattedQueue);
            setError(null);
        } catch (err) {
            console.error('Error in fetchQueueFromDB:', err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };
    
    const fetchSummary = async () => {
        try {
            const { data, error } = await supabase
                .from('Appointments')
                .select('status, actual_wait_seconds, ClinicID');
            
            if (error) {
                console.error('Error fetching summary:', error);
                return;
            }
            
            if (!data) return;
            
            const filteredData = clinicId 
                ? data.filter(item => item.ClinicID === clinicId)
                : data;
            
            const waiting = filteredData.filter(a => a.status === 'waiting').length;
            const inConsultation = filteredData.filter(a => a.status === 'in_consultation').length;
            const completed = filteredData.filter(a => a.status === 'complete').length;
            
            const completedWithWait = filteredData.filter(a => a.status === 'complete' && a.actual_wait_seconds);
            let avgWait = 15;
            if (completedWithWait.length > 0) {
                const totalWait = completedWithWait.reduce((sum, a) => sum + (a.actual_wait_seconds || 0), 0);
                avgWait = Math.round(totalWait / completedWithWait.length / 60);
            }
            
            setSummary({
                total_waiting: waiting,
                in_consultation_count: inConsultation,
                completed_today: completed,
                average_wait_minutes: avgWait
            });
        } catch (err) {
            console.error('Error in fetchSummary:', err);
        }
    };
    
    // Complete the current consultation
    const completeConsultation = async (appointmentId) => {
        try {
            const appointment = queue.find(a => a.appointment_id === appointmentId);
            const updateData = { 
                status: 'complete',
                consultation_ended_at: new Date().toISOString()
            };
            
            if (appointment && appointment.arrived_at) {
                const arrived = new Date(appointment.arrived_at);
                const now = new Date();
                updateData.actual_wait_seconds = Math.floor((now - arrived) / 1000);
            }
            
            const { error } = await supabase
                .from('Appointments')
                .update(updateData)
                .eq('id', appointmentId);
            
            if (error) {
                console.error('Error completing consultation:', error);
                alert('Error: ' + error.message);
                return;
            }
            
            // Check if there's a next patient waiting
            const nextPatient = queue.find(p => p.patient_status === 'waiting');
            if (nextPatient) {
                await startConsultation(nextPatient.appointment_id);
            }
            
            await fetchQueueFromDB();
            await fetchSummary();
            
            if (socket) {
                socket.emit('status:update', {
                    appointmentId,
                    newStatus: 'complete',
                    staffId,
                    clinicId
                });
            }
            
            console.log(`Consultation completed for appointment ${appointmentId}`);
        } catch (err) {
            console.error('Error in completeConsultation:', err);
            alert('Error completing consultation');
        }
    };
    
    // Start consultation for a patient
    const startConsultation = async (appointmentId) => {
        try {
            const updateData = { 
                status: 'in_consultation',
                consultation_started_at: new Date().toISOString()
            };
            
            const { error } = await supabase
                .from('Appointments')
                .update(updateData)
                .eq('id', appointmentId);
            
            if (error) {
                console.error('Error starting consultation:', error);
                alert('Error: ' + error.message);
                return;
            }
            
            await fetchQueueFromDB();
            await fetchSummary();
            
            if (socket) {
                socket.emit('status:update', {
                    appointmentId,
                    newStatus: 'in_consultation',
                    staffId,
                    clinicId
                });
            }
            
            console.log(`Consultation started for appointment ${appointmentId}`);
        } catch (err) {
            console.error('Error in startConsultation:', err);
            alert('Error starting consultation');
        }
    };
    
    // Call next patient (brings the first waiting patient into consultation)
    const callNextPatient = async () => {
        const nextWaiting = queue.find(p => p.patient_status === 'waiting');
        
        if (!nextWaiting) {
            alert('No patients waiting in queue');
            return;
        }
        
        await startConsultation(nextWaiting.appointment_id);
    };
    
    if (loading) {
        return (
            <div style={{ padding: '40px', textAlign: 'center' }}>
                <h2>Loading Dashboard...</h2>
                <p>Fetching data from database...</p>
            </div>
        );
    }
    
    if (error) {
        return (
            <div style={{ padding: '40px', textAlign: 'center', color: 'red' }}>
                <h2>Error Loading Data</h2>
                <p>{error}</p>
                <button 
                    onClick={() => window.location.reload()}
                    style={{ padding: '10px 20px', marginTop: '20px', cursor: 'pointer' }}
                >
                    Retry
                </button>
            </div>
        );
    }
    
    const currentPatient = queue.find(p => p.patient_status === 'in_consultation');
    const waitingPatients = queue.filter(p => p.patient_status === 'waiting');
    
    return (
        <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif', maxWidth: '1400px', margin: '0 auto' }}>
            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', flexWrap: 'wrap', gap: '10px' }}>
                <div>
                    <h1>🏥 Clinic Queue Management Dashboard</h1>
                    <p>Welcome, {staffName || 'Staff Member'}</p>
                    <p>📍 Active Clinic: {clinicId || 'All Clinics'}</p>
                </div>
                <button 
                    onClick={callNextPatient}
                    disabled={waitingPatients.length === 0}
                    style={{
                        background: waitingPatients.length === 0 ? '#9ca3af' : '#10b981',
                        color: 'white',
                        border: 'none',
                        padding: '12px 24px',
                        borderRadius: '8px',
                        cursor: waitingPatients.length === 0 ? 'not-allowed' : 'pointer',
                        fontSize: '16px',
                        fontWeight: 'bold'
                    }}
                >
                    {waitingPatients.length === 0 ? '📭 No Patients Waiting' : '🔔 Call Next Patient'}
                </button>
            </div>
            
            {/* Stats Cards */}
            <div style={{ 
                display: 'grid', 
                gridTemplateColumns: 'repeat(4, 1fr)', 
                gap: '15px', 
                margin: '20px 0' 
            }}>
                <div style={{ padding: '20px', background: '#fef3c7', borderRadius: '8px', borderLeft: '4px solid #f59e0b' }}>
                    <div style={{ fontSize: '14px', color: '#92400e' }}>🕐 Waiting</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#92400e' }}>{summary.total_waiting}</div>
                </div>
                <div style={{ padding: '20px', background: '#d1fae5', borderRadius: '8px', borderLeft: '4px solid #10b981' }}>
                    <div style={{ fontSize: '14px', color: '#065f46' }}>💚 In Consultation</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#065f46' }}>{summary.in_consultation_count}</div>
                </div>
                <div style={{ padding: '20px', background: '#dbeafe', borderRadius: '8px', borderLeft: '4px solid #3b82f6' }}>
                    <div style={{ fontSize: '14px', color: '#1e3a8a' }}>✅ Completed Today</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#1e3a8a' }}>{summary.completed_today}</div>
                </div>
                <div style={{ padding: '20px', background: '#e9d5ff', borderRadius: '8px', borderLeft: '4px solid #8b5cf6' }}>
                    <div style={{ fontSize: '14px', color: '#4c1d95' }}>⏱️ Avg Wait Time</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#4c1d95' }}>{summary.average_wait_minutes} min</div>
                </div>
            </div>
            
            {/* Current Consultation Section */}
            {currentPatient && (
                <div style={{ 
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    color: 'white',
                    padding: '20px',
                    borderRadius: '12px',
                    marginBottom: '20px'
                }}>
                    <h3 style={{ margin: 0, marginBottom: '10px' }}>💚 Current Consultation</h3>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap' }}>
                        <div>
                            <div style={{ fontSize: '24px', fontWeight: 'bold' }}>{currentPatient.patient_name}</div>
                            <div style={{ fontSize: '14px', opacity: 0.9 }}>Wait time: {currentPatient.wait_display || `${currentPatient.waiting_minutes} min`}</div>
                            <div style={{ fontSize: '12px', opacity: 0.7 }}>Arrived: {currentPatient.arrived_time}</div>
                        </div>
                        <button 
                            onClick={() => completeConsultation(currentPatient.appointment_id)}
                            style={{
                                background: '#ffffff',
                                color: '#4c1d95',
                                border: 'none',
                                padding: '10px 20px',
                                borderRadius: '8px',
                                cursor: 'pointer',
                                fontSize: '14px',
                                fontWeight: 'bold'
                            }}
                        >
                            ✓ Complete & Call Next
                        </button>
                    </div>
                </div>
            )}
            
            {/* Waiting Queue Table */}
            <h3>🕐 Waiting Queue ({waitingPatients.length} patients)</h3>
            <div style={{ background: 'white', borderRadius: '8px', border: '1px solid #e5e7eb', overflow: 'hidden' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                    <thead>
                        <tr style={{ background: '#f9fafb', borderBottom: '1px solid #e5e7eb' }}>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Position</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Patient Name</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Wait Time</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Type</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Reason</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {waitingPatients.map((patient) => (
                            <tr key={patient.appointment_id} style={{ borderBottom: '1px solid #e5e7eb' }}>
                                <td style={{ padding: '12px', fontWeight: 'bold' }}>{patient.queue_position}</td>
                                <td style={{ padding: '12px' }}>{patient.patient_name}</td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{ color: patient.wait_color, fontWeight: patient.waiting_minutes > 30 ? 'bold' : 'normal' }}>
                                        {patient.wait_display || `${patient.waiting_minutes} min`}
                                    </span>
                                    <div style={{ fontSize: '10px', color: '#999' }}>
                                        Arrived: {patient.arrived_time}
                                    </div>
                                </td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{
                                        padding: '2px 8px',
                                        borderRadius: '12px',
                                        fontSize: '12px',
                                        background: patient.is_walk_in ? '#fed7aa' : '#bfdbfe',
                                        color: patient.is_walk_in ? '#9a3412' : '#1e40af'
                                    }}>
                                        {patient.is_walk_in ? 'Walk-in' : 'Scheduled'}
                                    </span>
                                </td>
                                <td style={{ padding: '12px', fontSize: '13px' }}>{patient.reason}</td>
                                <td style={{ padding: '12px' }}>
                                    <button 
                                        onClick={() => startConsultation(patient.appointment_id)}
                                        style={{
                                            background: '#10b981',
                                            color: 'white',
                                            border: 'none',
                                            padding: '6px 12px',
                                            borderRadius: '6px',
                                            cursor: 'pointer',
                                            fontSize: '12px'
                                        }}
                                    >
                                        Start Now
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            
            {waitingPatients.length === 0 && !currentPatient && (
                <div style={{ textAlign: 'center', padding: '60px', color: '#6b7280' }}>
                    <div style={{ fontSize: '48px', marginBottom: '20px' }}>🏥</div>
                    <h3>No patients in queue</h3>
                    <p>Patients will appear here when they check in at reception.</p>
                </div>
            )}
            
            {/* Debug Info */}
            <details style={{ marginTop: '20px', padding: '10px', background: '#f3f4f6', borderRadius: '8px' }}>
                <summary style={{ cursor: 'pointer', fontWeight: 'bold' }}>Debug Info</summary>
                <pre style={{ fontSize: '12px', marginTop: '10px', overflow: 'auto' }}>
                    Active Queue: {queue.length} patients
                    Waiting: {summary.total_waiting}
                    In Consultation: {summary.in_consultation_count}
                    Completed: {summary.completed_today}
                </pre>
            </details>
        </div>
    );
};

export default StaffDashboard;
